// ====================================
// OBTENER NEXT ID
// ====================================
const filas = $input.all();
if (!filas || filas.length === 0) {
  return [{ nextId: 1 }];
}
const ids = filas.map(fila => {
  const primerValor = Object.values(fila.json)[1];
  return parseInt(primerValor) || 0;
});
const nextId = Math.max(...ids) + 1;

// ====================================
// FECHA Y HORA ARGENTINA
// ====================================
const ahora = new Date();
const ahoraAR = new Date(
  ahora.toLocaleString("en-US", { timeZone: "America/Argentina/Buenos_Aires" })
);
const diaSemana = ahoraAR.getDay();
const horaMin = ahoraAR.getHours() * 60 + ahoraAR.getMinutes();

// ====================================
// FERIADOS ARGENTINA 2026
// ====================================
const feriados = [
  "2026-01-01","2026-02-16","2026-02-17","2026-03-24",
  "2026-04-02","2026-04-03","2026-05-01","2026-05-25",
  "2026-06-15","2026-06-20","2026-07-09","2026-12-08","2026-12-25"
];

function esFeriado(date) {
  const iso = date.getFullYear() + "-" +
    (date.getMonth()+1).toString().padStart(2,"0") + "-" +
    date.getDate().toString().padStart(2,"0");
  return feriados.includes(iso);
}

function esFinDeSemana(date) {
  return date.getDay() === 0; // solo domingo
}

function avanzarADiaHabil(date) {
  const d = new Date(date);
  while (esFeriado(d) || esFinDeSemana(d)) {
    d.setDate(d.getDate() + 1);
  }
  return d;
}

// ====================================
// CALCULAR PRIMERA FECHA DE ENTREGA
// ====================================
let primeraFecha = new Date(ahoraAR);

// Regla especial 30/12/2025
if (
  ahoraAR.getFullYear() === 2025 &&
  ahoraAR.getMonth() === 11 &&
  ahoraAR.getDate() === 30
) {
  if (horaMin <= 16 * 60) {
    primeraFecha = new Date("2025-12-31T00:00:00");
  } else {
    primeraFecha = new Date("2026-01-02T00:00:00");
  }
} else {
  if (diaSemana >= 1 && diaSemana <= 5) {
    if (horaMin > 7 * 60) {
      primeraFecha.setDate(primeraFecha.getDate() + 1);
    }
  } else if (diaSemana === 6) {
    if (horaMin > 7 * 60) {
      primeraFecha.setDate(primeraFecha.getDate() + 2);
    }
  } else {
    primeraFecha.setDate(primeraFecha.getDate() + 1);
  }
}

primeraFecha = avanzarADiaHabil(primeraFecha);

// ====================================
// GENERAR LOS 5 TURNOS SIGUIENTES
// ====================================
const dias = ["Domingo","Lunes","Martes","Miércoles","Jueves","Viernes","Sábado"];

const turnos = [];
let fechaActual = new Date(primeraFecha);

for (let i = 0; i < 5; i++) {
  const iso = fechaActual.getFullYear() + "-" +
    (fechaActual.getMonth()+1).toString().padStart(2,"0") + "-" +
    fechaActual.getDate().toString().padStart(2,"0");

  const formateada =
    dias[fechaActual.getDay()] + " " +
    fechaActual.getDate().toString().padStart(2,"0") + "/" +
    (fechaActual.getMonth()+1).toString().padStart(2,"0") + "/" +
    fechaActual.getFullYear();

  turnos.push({
    turno: i + 1,
    fechaISO: iso,
    fechaFormateada: formateada
  });

  // Avanzar al siguiente día hábil
  fechaActual.setDate(fechaActual.getDate() + 1);
  fechaActual = avanzarADiaHabil(fechaActual);
}

// ====================================
// RETORNO FINAL
// ====================================
return [{
  nextId,
  turnos,                                      // array con los 5 turnos
  turno1: turnos[0].fechaFormateada,           // acceso directo para el prompt
  turno2: turnos[1].fechaFormateada,
  turno3: turnos[2].fechaFormateada,
  turno4: turnos[3].fechaFormateada,
  turno5: turnos[4].fechaFormateada,
  fechaEntregaISO: turnos[0].fechaISO,         // primera fecha (default)
  fechaEntregaFormateada: turnos[0].fechaFormateada,
  diaSemana: dias[ahoraAR.getDay()],
  horaActual:
    ahoraAR.getHours().toString().padStart(2,"0") + ":" +
